# Static count: FLEngine IAT + delay IAT vs the answer table (imports_table.rs TABLE), by category.
# usage: PYTHONDONTWRITEBYTECODE=1 python3 imports_vs_table.py PE.dll imports_table.rs OUT.tsv
# Reads only. Output columns: dll, name, kind(iat|delay), row(row|none), category
import re, sys, pefile

pe_path, table_path, out = sys.argv[1:4]
pe = pefile.PE(pe_path)

rows = set()
for ln in open(table_path, encoding="utf-8"):
    m = re.match(r'\s*\("([^"]+)",\s*"([^"]+)",\s*"fle_imp_', ln)
    if m:
        rows.add((m.group(1).lower(), m.group(2)))

