cats = [(n, re.compile(rx)) for n, rx in CAT]


def cat_of(name):
    for n, rx in cats:
        if rx.match(name):
            return n
    return "other"


out_rows = []
for kind, entries in (("iat", getattr(pe, "DIRECTORY_ENTRY_IMPORT", [])),
                      ("delay", getattr(pe, "DIRECTORY_ENTRY_DELAY_IMPORT", []))):
    for d in entries:
        dll = d.dll.decode().lower()
        for i in d.imports:
            if not i.name:
                continue
            name = i.name.decode()
            row = "row" if (dll, name) in rows else "none"
            out_rows.append((dll, name, kind, row, cat_of(name)))

with open(out, "w", encoding="utf-8") as f:
    f.write("dll\tname\tkind\trow\tcategory\n")
    for r in sorted(out_rows):
        f.write("\t".join(r) + "\n")

from collections import Counter
c = Counter((r[4], r[3]) for r in out_rows)
cats_seen = sorted(set(r[4] for r in out_rows))
print("table rows:", len(rows), " imports:", len(out_rows))
print("%-22s %6s %6s %6s" % ("category", "row", "none", "total"))
for cn in cats_seen:
    print("%-22s %6d %6d %6d" % (cn, c[(cn, "row")], c[(cn, "none")], c[(cn, "row")] + c[(cn, "none")]))
print("%-22s %6d %6d %6d" % ("ALL", sum(v for (a, b), v in c.items() if b == "row"), sum(v for (a, b), v in c.items() if b == "none"), len(out_rows)))
